#!/usr/bin/env python3
from pwn import *
import re

# Connect to the server
HOST = 'crypto.chal.csaw.io'
PORT = 8000

def detect_flag(text):
    # Look for flag pattern
    flag_pattern = r'flag{[^}]*}'
    match = re.search(flag_pattern, text)
    if match:
        print("FLAG FOUND:", match.group(0))
        return True
    return False

def detect_mode_of_operation(data):
    # Analyze received data for ECB/CBC patterns
    blocks = [data[i:i+16] for i in range(0, len(data), 16)]
    has_repeating_blocks = len(blocks) != len(set(blocks))

    if has_repeating_blocks:
        return "ECB mode detected (identical blocks found)"
    else:
        return "Likely CBC mode (no identical blocks)"

def main():
    r = remote(HOST, PORT)

    while True:
        try:
            # Receive data from server
            data = r.recvuntil(b'\n', timeout=2).decode('latin-1')

            # Check for flag
            if detect_flag(data):
                break

            # If data contains hex-encoded content
            if '0x' in data:
                try:
                    # Extract hex string
                    hex_str = data.strip().split('0x')[1]
                    # Convert to bytes
                    ciphertext = bytes.fromhex(hex_str)
                    print(f"\nReceived ciphertext (hex):", hex_str)
                    print(detect_mode_of_operation(ciphertext))
                except Exception as e:
                    pass

            # Send newline if needed
            r.sendline(b'')

        except EOFError:
            print("Connection closed by server")
            break
        except Exception as e:
            continue

if __name__ == '__main__':
    main()

